//! LC1 sole production loaded-world consumer. Preparation/lookup/durability and
//! reconciliation run as typed workers; Core only snapshots and commits results.
use super::*;
use nt2_desktop_g0::{world_local as local,world_lifecycle::{Coordinator,Stage,Ticket},protocol_lifecycle::{self as codec,wire as w},connection_time::{Stamp,Deadline},startup_local::Prepared};
#[path="next_world_auth.rs"]mod credentials;
use credentials::Call;
struct PreparationFence(Arc<AtomicU64>);
impl Default for PreparationFence{fn default()->Self{Self(Arc::new(AtomicU64::new(1)))}}
// Lifecycle ownership can advance before Start creates participant generation1.
// This volatile pair is installed only with a validated current admission; it
// is never restored as playing authority from the durable world record.
#[derive(Clone)]pub(super) struct AdmittedGenerations{pub(super) lifecycle:u64,pub(super) participant:u32,pub(super) ticket:Ticket}
#[derive(Default)]pub(super) struct Transport{
 pub(super) coordinator:Coordinator,pub(super) record:Option<local::Record>,draft:Option<local::Record>,
 pub(super) bridge:Option<Arc<crate::pipe::world::Bridge>>,pub(super) ctx:Option<admission::Context>,
 prepare:Option<tokio::task::JoinHandle<Result<PreparedReady,String>>>,lookup:Option<tokio::task::JoinHandle<Result<Option<local::Record>,String>>>,
 network:Option<tokio::task::JoinHandle<Result<Reconciled,String>>>,lookup_key:String,lookup_selector:Option<(crate::local_owner::Id,[u8;16],local::Marker)>,
 persist:Option<tokio::task::JoinHandle<Result<local::Record,String>>>,persist_intent:Option<local::Record>,persist_scope:Option<(uuid::Uuid,local::Identity,local::Intent)>,
 pub(super) native:Option<(crate::local_owner::Id,[u8;16])>,chosen:bool,pub(super) wants_prepare:bool,next:Option<Instant>,sequence:u64,
 optional:Option<tokio::task::JoinHandle<Result<OptionalReady,String>>>,pub(super) optional_next:Option<Instant>,pub(super) lobby_observed:Option<(String,Instant)>,
 persist_reply:Option<local::Record>,confirmed_digest:Option<[u8;32]>,confirmed:Option<Confirmed>,pub(super) waiting_for_start:bool,pub(super) host_started:bool,
 offline:Option<tokio::task::JoinHandle<Result<OfflineReady,String>>>,offline_ack:bool,
 #[cfg(test)]pub(super) cut_before_attempt:Arc<AtomicU64>,
 #[cfg(test)]pub(super) verification_hook:Option<Arc<dyn Fn()+Send+Sync>>,
 preparation_fence:PreparationFence,
 pub(super) admitted_generations:Option<AdmittedGenerations>,
 prepare_call:Option<Call>,network_call:Option<Call>,credential_result:Value,credential_failure:Value,
}
struct OfflineReady{scope:String,record:local::Record,response:w::Response}

