 #[test]fn lc1_slow_installation_verifier_keeps_actor_responsive_and_never_grants_before_success(){tauri::async_runtime::block_on(async{
  let(mut c,_,_,_)=fixture();c.game=None;*c.pending.lock().unwrap()=None;c.world.record=None;c.world.native=None;c.world.chosen=false;c.world.optional_next=Some(Instant::now()+Duration::from_secs(60));c.world.next=Some(Instant::now()+Duration::from_secs(60));c.room.as_mut().unwrap().state=Some("staging".into());c.info=Some(wire::Info{profile:Some(wire::CompatibilityProfile::default()),..Default::default()});c.game_path=Some(c.claims_root.join("missing-verifier-fixture"));
  let gate=Arc::new((Mutex::new(false),std::sync::Condvar::new()));let held=gate.clone();let(entered,observed)=std::sync::mpsc::channel();
  c.world.verification_hook=Some(Arc::new(move||{let _=entered.send(());let(lock,wake)=&*held;let released=lock.lock().unwrap();let _=wake.wait_timeout_while(released,Duration::from_secs(3),|r|!*r).unwrap();}));
  let began=Instant::now();c.lc1_prepare().unwrap();let dispatch=began.elapsed();
  tokio::task::spawn_blocking(move||observed.recv_timeout(Duration::from_secs(1)).unwrap()).await.unwrap();
  // Prevent unrelated auth/optional work; the exact verifier job remains held.
  c.desktop=None;c.room=None;c.world.wants_prepare=false;let bridge=c.world.bridge.as_ref().unwrap().clone();
  let stop=Arc::new(std::sync::atomic::AtomicBool::new(false));let(handle,actor)=crate::next_app::scheduler::new(c,stop.clone());let actor=tokio::spawn(actor);
  let response=tokio::time::timeout(Duration::from_millis(750),handle.command(|c|Box::pin(async move{assert!(c.world.prepare.is_some());assert!(c.pending.lock().unwrap().is_none());assert!(c.world.bridge.as_ref().unwrap().pending.lock().unwrap().is_none());assert!(c.world_files.snapshot()["commits"].as_u64().unwrap_or(0)==0);Ok(json!("responsive before verification"))}))).await;
  {let(lock,wake)=&*gate;*lock.lock().unwrap()=true;wake.notify_all();}stop.store(true,Ordering::Release);actor.await.unwrap();
  assert!(dispatch<Duration::from_millis(100),"Preparation hashed installation on the actor: {dispatch:?}");assert_eq!(response.unwrap().unwrap(),"responsive before verification");assert!(bridge.pending.lock().unwrap().is_none(),"Failed verification armed startup authority");
 });}
