impl<S:CredentialStore> Core<S>{
    /// Physical local contact for read-only Race metadata, never game authority.
    pub(super) fn race_readonly_metadata(&self,p:&handoff::Pending)->bool{
        self.lc1&&self.room.as_ref().is_some_and(|room|room.config.as_ref().and_then(|c|c.mode.as_deref())==Some("race")&&self.world.record.as_ref().is_some_and(|r|
              r.intent==nt2_desktop_g0::world_local::Intent::Terminal&&r.identity.origin==self.base&&r.identity.service==self.service&&r.identity.device==self.device&&Some(&r.identity.room)==room.room_id.as_ref()&&r.identity.run==p.run&&r.identity.run_epoch==p.epoch&&r.identity.config==p.config&&p.matches_seed(r.seed.as_deref())&&self.desktop.as_ref().is_some_and(|d|d.account==r.identity.account)))
              // Terminal persistence retires the recovery ticket. The retained
              // accepted physical binding is sufficient for read-only metadata.
              &&p.native_v2&&p.accepted&&p.loaded&&p.native_epoch.is_some_and(|epoch|epoch>0)&&p.owner.is_some()&&p.owner==self.world.native&&p.generation.as_ref().is_some_and(|(g,n)|Arc::ptr_eq(g,&self.generation)&&g.load(Ordering::Acquire)==*n)
            &&p.last_seen.is_some_and(|t|t.elapsed()<Duration::from_secs(12))&&p.owner.is_some_and(|o|crate::pipe::owner_instance(o.0).is_some())
    }
}
